// backgroundRenderer.js
import { CONFIG } from './config.js';

export class BackgroundRenderer {
  constructor() {
    this.animT = 0;
    this.customBackgroundImage = null;
    this.isIOSDevice = false;
    this.loadCustomBackground();
  }

  setIOSDevice(isIOS) { this.isIOSDevice = !!isIOS; }
  setVideoElement(videoEl) { this.videoEl = videoEl || null; }

  loadCustomBackground() {
    const img = new Image();
    img.onload = () => { this.customBackgroundImage = img; };
    img.onerror = () => {};
    const base = import.meta.env.BASE_URL || '/';
    img.src = base + 'DefenderBg.png';
  }

  setCustomBackground(src) {
    const img = new Image();
    img.onload = () => { this.customBackgroundImage = img; };
    img.onerror = () => {};
    img.src = src;
  }

  updateAnimation() { this.animT += 0.016; }

  renderBackgroundTo(ctx, w, h, bgVideoEl, bgMoonVideoEl /* iosMoonVideoEl */) {
    const bgType =
      (CONFIG.BACKGROUND && CONFIG.BACKGROUND.TYPE) ||
      (CONFIG.BACKGROUND_EFFECTS && CONFIG.BACKGROUND_EFFECTS.DEFAULT_BACKGROUND) ||
      'original';

    const intensity =
      (CONFIG.BACKGROUND && typeof CONFIG.BACKGROUND.INTENSITY === 'number'
        ? CONFIG.BACKGROUND.INTENSITY
        : (CONFIG.BACKGROUND_EFFECTS && CONFIG.BACKGROUND_EFFECTS.EFFECT_INTENSITY)) ?? 0.5;

    ctx.clearRect(0, 0, w, h);
    this.updateAnimation();

    if (bgType === 'original') return;

    if (bgType === 'waves')     { this.renderWaveBackground(ctx, w, h, intensity); return; }
    if (bgType === 'frequency') { this.renderFrequencyBackground(ctx, w, h, intensity); return; }
    if (bgType === 'video' && bgVideoEl) {
      this.renderVideoBackground(ctx, w, h, bgVideoEl, intensity); return;
    }
    if (bgType === 'moon_video' && bgMoonVideoEl) {
      this.renderMoonVideoBackground(ctx, w, h, bgMoonVideoEl, intensity); return;
    }

    // person_overlay：背景層保持透明（不再把相機畫滿）
    if (bgType === 'person_overlay') {
      return;
    }

    if (bgType === 'custom_moon_bg') {
      this.renderCustomMoonBackground(ctx, w, h, bgMoonVideoEl, intensity);
      return;
    }
  }

  // ---- effects ----
  renderWaveBackground(ctx, w, h, intensity) {
    const grad = ctx.createLinearGradient(0, 0, w, h);
    grad.addColorStop(0, '#1a2332');
    grad.addColorStop(0.5, '#2d3a50');
    grad.addColorStop(1, '#0f1419');
    ctx.fillStyle = grad; ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = `rgba(100,200,255,${intensity * 0.6})`; ctx.lineWidth = 2;
    for (let i = 0; i < 8; i++) {
      ctx.beginPath();
      for (let x = 0; x < w; x += 5) {
        const off = i * 50;
        const y = h / 2 + Math.sin((x + off) * 0.012 + this.animT * 1.2) * 20 * intensity;
        if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
  }

  renderFrequencyBackground(ctx, w, h, intensity) {
    ctx.fillStyle = '#0a0a0a'; ctx.fillRect(0, 0, w, h);
    const bands = 48, bw = w / bands;
    for (let i = 0; i < bands; i++) {
      const x = i * bw;
      const bh = (Math.sin(this.animT * 2 + i * 0.2) * 0.5 + 0.5) * h * 0.5 * intensity;
      const hue = (this.animT * 30 + i * 10) % 360;
      ctx.fillStyle = `hsla(${hue},70%,60%,0.8)`; ctx.fillRect(x, h - bh, bw - 1, bh);
    }
  }

  renderVideoBackground(ctx, w, h, v, intensity) {
    const vw = v.videoWidth || 1, vh = v.videoHeight || 1;
    if (v.readyState >= 2) {
      const s = Math.max(w / vw, h / vh), dw = Math.round(vw * s), dh = Math.round(vh * s);
      const ox = Math.round((w - dw) / 2), oy = Math.round((h - dh) / 2);
      try { if (v.paused) v.play().catch(() => {}); } catch {}
      ctx.globalAlpha = Math.min(1, 0.3 + intensity * 0.7);
      ctx.drawImage(v, 0, 0, vw, vh, ox, oy, dw, dh);
      ctx.globalAlpha = 1;
    }
  }

  renderMoonVideoBackground(ctx, w, h, v, intensity) {
    try {
      if (v.readyState >= 2 && !v.paused) {
        const vw = v.videoWidth || v.width || 1, vh = v.videoHeight || v.height || 1;
        const s = Math.max(w / vw, h / vh), dw = Math.round(vw * s), dh = Math.round(vh * s);
        const ox = Math.round((w - dw) / 2), oy = Math.round((h - dh) / 2);
        ctx.globalAlpha = Math.min(1, 0.3 + intensity * 0.7);
        ctx.drawImage(v, 0, 0, vw, vh, ox, oy, dw, dh);
        ctx.globalAlpha = 1;
      } else if (v.paused) {
        v.play().catch(() => {});
      }
    } catch {}
  }

  renderCustomMoonBackground(ctx, w, h, v, intensity) {
    // iOS：只畫靜態圖；月亮由前景透明影片處理
    if (this.isIOSDevice) {
      if (this.customBackgroundImage) {
        const img = this.customBackgroundImage;
        const iw = img.naturalWidth || img.width, ih = img.naturalHeight || img.height;
        if (iw && ih) {
          const s = Math.max(w / iw, h / ih), dw = Math.round(iw * s), dh = Math.round(ih * s);
          const ox = Math.round((w - dw) / 2), oy = Math.round((h - dh) / 2);
          ctx.drawImage(img, 0, 0, iw, ih, ox, oy, dw, dh);
        }
      }
      return;
    }

    // 非 iOS：靜態圖 + 圓形月亮（仍保留）
    if (this.customBackgroundImage) {
      const img = this.customBackgroundImage;
      const iw = img.naturalWidth || img.width, ih = img.naturalHeight || img.height;
      if (iw && ih) {
        const s = Math.max(w / iw, h / ih), dw = Math.round(iw * s), dh = Math.round(ih * s);
        const ox = Math.round((w - dw) / 2), oy = Math.round((h - dh) / 2);
        ctx.drawImage(img, 0, 0, iw, ih, ox, oy, dw, dh);
      }
    }
    if (v && v.readyState >= 2 && !v.paused) {
      this.renderCircularMoon(ctx, w, h, v, intensity);
    } else if (v && v.paused) {
      v.play?.().catch(() => {});
    }
  }

  renderCircularMoon(ctx, w, h, v, intensity) {
    const vw = v.videoWidth || v.width || 1, vh = v.videoHeight || v.height || 1;
    if (!(vw > 1 && vh > 1)) return;
    ctx.save();
    const ar = w / h;
    let cx, cy, r;
    if (ar > 0.6) { cx = w * 0.5;  cy = h * 0.35; r = Math.min(w, h) * 0.25; }
    else if (ar > 0.5) { cx = w * 0.51; cy = h * 0.29; r = Math.min(w, h) * 0.29; }
    else { cx = w * 0.51; cy = h * 0.26; r = Math.min(w, h) * 0.30; }

    ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.clip();
    const s = Math.max(w / vw, h / vh), dw = Math.round(vw * s), dh = Math.round(vh * s);
    const ox = Math.round((w - dw) / 2), oy = Math.round((h - dh) / 2);
    ctx.globalAlpha = Math.min(1, 0.8 + intensity * 0.2);
    ctx.drawImage(v, 0, 0, vw, vh, ox, oy, dw, dh);
    ctx.globalAlpha = 1;
    ctx.restore();
  }
}